const stripDataUrl = (url) => url.split(",")[1] || url;
const mimeFromDataUrl = (url) => url.startsWith("data:image/png") ? "image/png" : "image/jpeg";
const pickImageMedia = (file) => ["image/jpeg", "image/png", "image/webp"].includes(file.type) ? file.type : "image/jpeg";

// FileReader → base64 puro (sin el prefijo data:)
function fileToBase64(file) {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => res(r.result.split(",")[1]);
    r.onerror = rej;
    r.readAsDataURL(file);
  });
}

// Comprime imagen vía canvas → dataURL JPEG. Rechaza la promesa si falla la lectura/carga.
function compressImageToDataUrl(file, maxW = 800, quality = 0.82) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const scale = Math.min(1, maxW / img.width);
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = reject;
      img.src = reader.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

/**
 * HTML de la ventana de espera de los PDF con IA, con cronómetro en vivo.
 * Un cartel estático durante 40 s parece que la app se colgó y el usuario
 * cierra la ventana; ver el tiempo correr evita esa falsa alarma.
 */
// La ventana de espera se abre aparte; C.lime aquí sería una variable CSS que
// esa ventana no tiene definida, así que va el verde literal.
function htmlEsperaIA(titulo, subtitulo, color = "#4d7c0f") {
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="background:#f5f7f0;color:${color};font-family:system-ui,sans-serif;display:flex;align-items:center;justify-content:center;height:100vh;margin:0;text-align:center">
  <div>
    <div style="width:38px;height:38px;border:3px solid rgba(27,31,22,.12);border-top-color:${color};border-radius:50%;animation:g 1s linear infinite;margin:0 auto 16px"></div>
    <p style="font-size:19px;margin:0 0 6px">${titulo}</p>
    <p style="font-size:13px;color:#5f6b57;margin:0">${subtitulo}</p>
    <p id="t" style="font-size:12px;color:#6b7280;margin-top:12px">0 s</p>
    <p id="avi" style="font-size:11.5px;color:#6b7280;margin-top:6px;max-width:260px"></p>
  </div>
  <style>@keyframes g{to{transform:rotate(360deg)}}</style>
  <script>
    var s=0, el=document.getElementById('t'), avi=document.getElementById('avi');
    setInterval(function(){
      s++; el.textContent = s + ' s';
      if (s === 25) avi.textContent = 'Sigue en curso. Los modelos gratuitos suelen tardar más.';
      if (s === 90) avi.textContent = 'Está tardando de más. Si no responde, prueba con otro modelo en Perfil → Ajustes.';
    }, 1000);
  <\/script>
</body></html>`;
}

/**
 * fetch con límite de tiempo. Sin esto, una clave lenta o colgada bloquea la
 * petición indefinidamente y, como las claves se prueban EN SERIE, el usuario
 * puede esperar minutos antes de ver un resultado o un error.
 */
async function fetchConTimeout(url, opciones, ms) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), ms);
  try {
    return await fetch(url, { ...opciones, signal: ctrl.signal });
  } catch (e) {
    if (e.name === "AbortError") {
      throw new Error(`Sin respuesta en ${Math.round(ms / 1000)} s`);
    }
    throw e;
  } finally {
    clearTimeout(t);
  }
}

// Márgenes de espera: las peticiones con imagen/PDF tardan legítimamente más
const TIMEOUT_TEXTO_MS = 45000;
const TIMEOUT_MEDIA_MS = 90000;

async function callGemini(messages, systemInstruction, responseSchema = null, options = {}) {
  let apiKeysStr = await loadKey("gemini_api_key", "");
  
  let apiKeys = [];
  if (apiKeysStr && apiKeysStr.trim() !== "") {
    apiKeys = apiKeysStr.split(/[,;\s]+/).map(k => k.trim()).filter(k => k.length > 0);
  }
  
  const defaultKeys = DEFAULT_GEMINI_KEY.split(/[,;\s]+/).map(k => k.trim()).filter(k => k.length > 0);
  
  // Agregar las llaves por defecto al final como respaldo si no están presentes
  defaultKeys.forEach(dk => {
    if (!apiKeys.includes(dk)) {
      apiKeys.push(dk);
    }
  });

  if (apiKeys.length === 0) {
    throw new Error("No API Key configurada. Ve a Perfil → Ajustes y agrega tu clave gratuita de aistudio.google.com");
  }

  // Solo se usan claves nativas de Gemini. Las de OpenRouter (sk-or-) se
  // descartan: iban por cola compartida en los modelos gratuitos y eran la
  // causa principal de las esperas largas.
  const geminiKeys = apiKeys.filter(k => !k.startsWith("sk-or-"));
  if (geminiKeys.length === 0) {
    throw new Error("Necesitas una API Key de Gemini. Consíguela gratis en aistudio.google.com y añádela en Perfil → Ajustes.");
  }

  // Round-robin estricto: cada llamada empieza en la siguiente clave
  const orderedKeys = [];
  const startGemini = _rrIdx % geminiKeys.length;
  _rrIdx = (_rrIdx + 1) % geminiKeys.length;
  for (let count = 0; count < geminiKeys.length; count++) {
    orderedKeys.push(geminiKeys[(startGemini + count) % geminiKeys.length]);
  }

  let lastError = null;
  // Las llamadas con imagen o PDF necesitan más margen que las de solo texto
  const llevaMedia = messages.some(m => Array.isArray(m.content) && m.content.some(p => p.type === "image"));
  const timeoutMs = options.timeoutMs || (llevaMedia ? TIMEOUT_MEDIA_MS : TIMEOUT_TEXTO_MS);

  for (let idx = 0; idx < orderedKeys.length; idx++) {
    const apiKey = orderedKeys[idx];
    try {
        // Endpoint directo de Google Gemini
        const contents = messages.map(m => {
          if (Array.isArray(m.content)) {
            const parts = m.content.map(part => {
              if (part.type === "image") {
                return {
                  inlineData: {
                    mimeType: part.source.media_type,
                    data: part.source.data
                  }
                };
              }
              return { text: part.text };
            });
            return { role: m.role === "assistant" ? "model" : "user", parts };
          }
          return {
            role: m.role === "assistant" ? "model" : "user",
            parts: [{ text: m.content }]
          };
        });

        const nativeModel = (await loadKey("gemini_native_model", "gemini-2.5-flash")) || "gemini-2.5-flash";
        const url = `https://generativelanguage.googleapis.com/v1beta/models/${nativeModel}:generateContent?key=${apiKey}`;
        
        const generationConfig = {
          temperature: 0.2,
          // 8192 se quedaba corto para el plan de rutina y la respuesta llegaba
          // cortada a media lista de ejercicios. Y en texto libre, 2048 se los
          // come el propio razonamiento del modelo antes de escribir nada:
          // el análisis de tendencia acababa cortado a media frase.
          maxOutputTokens: options.maxTokens || (responseSchema ? 24576 : 8192)
        };
        
        if (responseSchema) {
          generationConfig.responseMimeType = "application/json";
          generationConfig.responseSchema = responseSchema;
          // thinkingBudget:0 causes empty responses on gemini-2.5-flash + JSON schema
          // Only disable thinking on 2.0/1.5 models; let 2.5+ use default thinking
          if (!nativeModel.includes("2.5") && !nativeModel.includes("2.0-flash-thinking")) {
            generationConfig.thinkingConfig = { thinkingBudget: 0 };
          }
        } else if (nativeModel.includes("2.5-flash")) {
          // EL FALLO: esto solo se ponía cuando había esquema JSON. En texto
          // libre el razonamiento nunca se limitaba, y sale del MISMO
          // maxOutputTokens — así que se lo comía antes de escribir y las
          // respuestas llegaban cortadas a media frase, dejando incluso un
          // "**" sin cerrar. Aquí no hay esquema, así que 0 es seguro.
          generationConfig.thinkingConfig = { thinkingBudget: 0 };
        }

        const body = {
          contents,
          systemInstruction: {
            parts: [{ text: systemInstruction }]
          },
          generationConfig
        };
        if (options.safetySettings) {
          body.safetySettings = options.safetySettings;
        }

        const res = await fetchConTimeout(url, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(body)
        }, timeoutMs);

        if (!res.ok) {
          const errorData = await res.json().catch(() => ({}));
          const errMsg = errorData.error?.message || `HTTP ${res.status}`;
          console.error(`[Gemini key ${idx+1}/${orderedKeys.length}] ${res.status}: ${errMsg}`);
          throw new Error(errMsg);
        }

        const data = await res.json();
        const candidate = data.candidates?.[0];
        const finishReason = candidate?.finishReason;
        if (finishReason === "SAFETY" || (!candidate && data.promptFeedback?.blockReason)) {
          const reason = data.promptFeedback?.blockReason || "SAFETY";
          throw new Error(`Bloqueado por filtros de seguridad (${reason}). Si estás analizando fotos corporales, intenta con imágenes de diferente ángulo.`);
        }
        const parts = candidate?.content?.parts || [];
        // gemini-2.5-flash thinking models prepend a {thought:true} part before the actual response
        const textPart = parts.find(p => !p.thought && p.text != null) || parts[parts.length - 1];
        const textOut = textPart?.text || "";
        if (finishReason === "MAX_TOKENS") {
          // Se devuelve igualmente: cleanAndParseJSON sabe reparar un JSON
          // cortado y suele salvarse casi todo el contenido.
          console.warn("[Gemini] respuesta cortada por límite de tokens; se intentará reparar");
          // En texto no hay nada que reparar, pero callar el corte es peor:
          // el usuario ve una frase a medias sin saber por qué
          if (!responseSchema && textOut) {
            return textOut.trim() + "\n\n*(La respuesta se cortó por longitud. Vuelve a pedirla para obtener el resto.)*";
          }
        }
        if (!textOut && responseSchema) {
          throw new Error("El modelo devolvió una respuesta vacía. Intenta de nuevo o cambia el modelo en Perfil → Ajustes.");
        }
        return textOut.trim();
    } catch (e) {
      lastError = e;
      const is429 = e.message && (e.message.includes("429") || e.message.includes("RESOURCE_EXHAUSTED") || e.message.includes("quota") || e.message.includes("limit"));
      console.warn(`Error con la API Key ${idx + 1}/${orderedKeys.length}: ${e.message}. Intentando con la siguiente...`);
      if (is429 && idx < orderedKeys.length - 1) {
        // backoff exponencial: 2s, 4s, 8s… entre claves
        await new Promise(r => setTimeout(r, Math.min(2000 * Math.pow(2, idx), 16000)));
      }
    }
  }

  const isQuota = lastError?.message && (lastError.message.includes("429") || lastError.message.includes("RESOURCE_EXHAUSTED") || lastError.message.includes("quota") || lastError.message.includes("limit"));
  if (isQuota) {
    throw new Error("⏱️ Límite de peticiones alcanzado en todas las claves. Si todas tus claves son de la misma cuenta de Google, comparten la misma cuota — crea claves desde cuentas distintas para multiplicarla. O espera 1 minuto e intenta de nuevo.");
  }
  throw lastError || new Error("No se pudo conectar con ninguna API Key.");
}

/**
 * Las consultas que la app lanza sola al coach llevan un prompt técnico entre
 * corchetes. Mostrarlo tal cual hacía parecer que el usuario había escrito un
 * párrafo que nunca tecleó, así que se sustituye por una etiqueta corta.
 */
function esPromptAutomatico(texto) {
  return typeof texto === "string" && /^\s*\[[^\]]+\]/.test(texto);
}
function etiquetaAutomatica(texto) {
  const m = typeof texto === "string" && texto.match(/^\s*\[([^\]]+)\]/);
  return m ? `✦ ${m[1]}` : "✦ Consulta automática";
}

